<!-- 主题综合页的跨领域数据库分析；计算口径公开，所有结果可回到实际记录。 -->
<template>
  <section class="topic-insights" aria-label="主题数据库分析">
    <header class="insights-head"><div><h2>从数据库看行业变化</h2><p>{{ data.records.length }} 条平台记录 · 当前范围 {{ data.filtered.length }} 条 · {{ data.uniqueSources }} 篇不同原文</p></div><label>分析窗口 <select v-model.number="months"><option :value="3">近3个自然月</option><option :value="6">近6个自然月</option><option :value="0">全部历史</option></select></label></header>
    <p class="scope">近期按发布日期统计，缺失时采用采集日期；对照为此前等长的自然月窗口。当前月未结束，条数变化只表示资料积累，不能作为行业增速。不同原文按去除跟踪参数后的 URL 去重，也不等于独立核验来源。</p>
    <div class="decision-grid">
      <article><span>领域关注变化</span><h3>{{ leading ? leading.name : '当前没有观察' }}</h3><p v-if="leading">当前窗口 {{ leading.count }} 条，{{ leading.distinctSources }} 篇不同原文。<template v-if="months">较上一窗口{{ leading.delta>0?'增加':leading.delta<0?'减少':'持平' }}{{ leading.delta ? ` ${Math.abs(leading.delta)} 条` : '' }}。</template>{{ leading.distinctSources < 3 ? '资料来源较少，优先补充交叉证据。' : '可进一步核对进展是否来自多个独立发布。' }}</p><button v-if="leading" type="button" @click="inspect(leading.items,`${leading.name} · 当前窗口`)">核对观察 ↗</button></article>
      <article><span>价值判断与交付阶段</span><h3>{{ data.highValue.length }} 条高价值判断，{{ data.product.length }} 条产品/API</h3><p>“极高/很高”是原记录的分析标注；产品/API 阶段也不等于付费部署。另有 {{ data.early.length }} 条停留在论文或厂商实验、{{ data.unmarked.length }} 条阶段未标注，应区分技术机会与已验证的客户价值。</p><button type="button" @click="inspect(data.highValue,'价值标注为极高/很高的观察')">查看判断依据 ↗</button></article>
      <article><span>来源与结论的可靠性</span><h3>{{ data.repeatedSourceRecords.length }} 篇原文被多条观察引用</h3><p>当前 {{ data.filtered.length }} 条观察对应 {{ data.uniqueSources }} 篇原文。一次公告拆成多条成果会放大资料数量；来源机构多也不自动代表客户验证或第三方复现。</p><button type="button" @click="inspect(unique(data.repeatedSourceRecords.flatMap(s=>s.items)),'共用原文的观察：需核对是否为同一发布拆条')">核对来源重复 ↗</button></article>
    </div>
    <section class="insight-panel"><div class="panel-title"><div><h2>领域进展与证据阶段</h2><p>将资料变化、来源覆盖、阶段标注与已保存的研判放在一起比较。</p></div></div><div class="table-scroll"><table><thead><tr><th>细分领域</th><th>本期观察</th><th>{{ months ? '前期 / 变化' : '对照' }}</th><th>不同原文</th><th>阶段分布</th><th>研判基础</th><th>进一步分析</th></tr></thead><tbody><tr v-for="row in orderedRows" :key="row.id"><td>{{ row.name }}</td><td><button class="count" type="button" @click="inspect(row.items,`${row.name} · 当前窗口`)">{{ row.count }}</button></td><td>{{ months ? `${row.previous} / ${row.delta>0?'+':''}${row.delta}` : '—' }}</td><td>{{ row.distinctSources }}</td><td><div class="stage-bar" :aria-label="stageDescription(row)"><i v-for="(stage,index) in stages" :key="stage" :title="`${stage}：${row.stages[stage]}`" :style="{width:`${row.count ? row.stages[stage]/row.count*100 : 0}%`,background:colors[index]}"></i></div><small>{{ stageDescription(row) }}</small></td><td>{{ row.report ? `置信度${confidence(row.report.confidence)}` : '尚无研判' }}<small>{{ row.freshness==='stale'?'有变更待吸收':row.report?'已有保存版本':'先补资料与判断' }}</small></td><td><button v-if="row.id" type="button" @click="$emit('openCategory',row.id)">细分研判 ↗</button></td></tr></tbody></table></div><div class="stage-legend"><span v-for="(stage,index) in stages" :key="stage"><i :style="{background:colors[index]}"></i>{{ stage }}</span></div><p class="scope">“工具/平台可用”“产品/API阶段”是交付形式标注，不是销售收入、量产交付或投资评级。未标注记录单独计入，不能推定处于早期。</p></section>
    <div class="insight-columns">
      <section class="insight-panel"><h2>机构与资料覆盖</h2><p class="scope">按来源机构原始字段统计，名称未做集团合并；一条观察可关联多个机构。这是资料覆盖，不是企业实力排名。</p><button v-for="org in data.organizations.slice(0,10)" :key="org.name" type="button" class="rank-row" @click="inspect(org.items,`${org.name} · 来源观察`)"><span>{{ org.name }}</span><i><b :style="{width:`${org.items.length/orgMax*100}%`}"></b></i><strong>{{ org.items.length }}</strong></button><p v-if="!data.organizations.length" class="empty">当前范围未标注来源机构。</p></section>
      <section class="insight-panel"><h2>哪些结论需要补证据</h2><p class="scope">按“有变更待吸收、原文少于3篇、研判置信度有限、观察缺口”提示采集重点，不自动判断领域技术水平。</p><article v-for="gap in data.gaps.slice(0,6)" :key="gap.id" class="gap-row"><strong>{{ gap.name }}</strong><p>{{ gap.reasons.join('；') }}。</p><div><button type="button" @click="$emit('collect',gap.id)">补充研究依据</button><button type="button" @click="$emit('openCategory',gap.id)">查看现有判断 ↗</button></div></article><p v-if="!data.gaps.length" class="empty">当前规则未检出覆盖缺口；这不表示所有结论都已充分验证。</p></section>
    </div>
    <section class="insight-panel"><h2>本版结论与当前资料的距离</h2><div class="distance-grid"><button type="button" @click="inspect(data.cited,'当前范围内被主题报告直接引用的观察')"><strong>{{ data.cited.length }}</strong><span>本版主题直接引用</span></button><button type="button" @click="inspect(data.afterCutoff,'本版资料截止后新增或修改的观察')"><strong>{{ data.afterCutoff.length }}</strong><span>截止后新增 / 修改</span></button><button type="button" @click="inspect(data.sourceMissing,'缺少有效原文 URL 的观察')"><strong>{{ data.sourceMissing.length }}</strong><span>缺少可追溯原文</span></button><button type="button" @click="inspect(data.sampleWarnings,'标题或元数据明确标注的展示样例')"><strong>{{ data.sampleWarnings.length }}</strong><span>明确标注的展示样例</span></button></div><p class="scope">以上按当前窗口统计。主题综合主要建立在细分研判上，“未被主题直接引用”不等于从未分析。样例保留在平台原计数中，但不应作为行业进展或商业化证据。</p></section>
    <section v-if="selection" ref="inspector" class="insight-panel evidence-inspector" aria-live="polite"><div class="panel-title"><div><h2>{{ selection.title }}</h2><p>共 {{ selection.items.length }} 条平台记录</p></div><button type="button" @click="selection=null">关闭</button></div><div v-if="selection.items.length"><button v-for="item in selection.items.slice((page-1)*10,page*10)" :key="item.id" type="button" class="evidence-row" @click="$emit('openObservation',item)"><time>{{ item.date || '日期未记录' }}</time><span><strong>{{ item.title }}</strong><small>{{ item.summary || '查看完整内容与引用来源' }}</small></span><b>↗</b></button><div class="paging"><button type="button" :disabled="page===1" @click="page--">上一页</button><span>{{ page }} / {{ Math.ceil(selection.items.length/10) }}</span><button type="button" :disabled="page*10>=selection.items.length" @click="page++">下一页</button></div></div><p v-else class="empty">当前范围内没有符合此条件的记录。</p></section>
  </section>
</template>
<script setup>
import { computed, nextTick, ref, watch } from 'vue'
import { buildTopicInsights } from './marketIntelTopicInsights.js'
const props=defineProps({observations:{type:Array,default:()=>[]},categories:{type:Array,default:()=>[]},report:{type:Object,default:null}})
defineEmits(['openObservation','openCategory','collect'])
const months=ref(3),selection=ref(null),page=ref(1),inspector=ref(null)
const stages=['研究论文','厂商自报实验','开放可复现','工具/平台可用','产品/API阶段','未标注']
const colors=['#b5cce5','#7fa8d3','#4d87bf','#2873a3','#238d76','#e2e6ea']
const data=computed(()=>buildTopicInsights(props.observations,props.categories,props.report,months.value))
const orderedRows=computed(()=>[...data.value.rows].sort((a,b)=>b.count-a.count||b.distinctSources-a.distinctSources))
const leading=computed(()=>orderedRows.value.find(r=>r.count))
const orgMax=computed(()=>Math.max(1,...data.value.organizations.map(o=>o.items.length)))
const confidence=value=>({high:'较高',medium:'中等',low:'有限'})[value]||'未标注'
const unique=items=>[...new Map(items.map(i=>[i.id,i])).values()]
const stageDescription=row=>stages.filter(s=>row.stages[s]).map(s=>`${s} ${row.stages[s]}`).join(' · ')||'暂无观察'
function inspect(items,title){selection.value={items:unique(items).sort((a,b)=>b.date.localeCompare(a.date)),title};page.value=1;nextTick(()=>inspector.value?.scrollIntoView({behavior:'smooth',block:'start'}))}
watch([months,()=>props.observations],()=>{selection.value=null})
</script>
<style scoped>
