ont-size:11px;color:#7d8d9a;margin-top:13px}.stage-legend i{display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:5px}.topic-insights .count{font-size:17px;font-weight:600;color:#315e86}.insight-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.insight-columns>.insight-panel{margin:0;align-self:start}.rank-row{display:flex;align-items:center;width:100%;gap:12px;margin:13px 0}.rank-row>span{width:45%;overflow-wrap:anywhere;color:#516b82}.rank-row>i{flex:1;height:7px;background:#edf1f5;border-radius:2px}.rank-row b{display:block;height:100%;background:#6494bf;border-radius:2px}.rank-row strong{width:22px;text-align:right;color:#48647c}.gap-row{border-top:1px solid #edf1f5;padding:12px 0}.gap-row>strong{font-size:14px}.gap-row p{font-size:12px;color:#7c8d9d;line-height:1.8;margin:5px 0}.gap-row>div{display:flex;gap:15px}.distance-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-top:18px}.distance-grid button{padding:16px;background:#f5f8fb;border-radius:5px;color:#7b8d9e}.distance-grid strong{display:block;font-size:28px;font-weight:500;color:#345977;margin-bottom:5px}.distance-grid span{font-size:12px}.evidence-row{display:flex;width:100%;gap:14px;padding:13px 0!important;border-bottom:1px solid #e7edf2!important;align-items:start}.evidence-row time{min-width:80px;color:#91a0ad;font-size:11px}.evidence-row>span{flex:1;min-width:0}.evidence-row strong{font-size:13px;font-weight:550}.evidence-row small{display:block;color:#8c9aa7;font-size:12px;line-height:1.8;margin-top:4px}.paging{display:flex;align-items:center;justify-content:end;gap:16px;color:#8a98a6;font-size:12px;margin-top:17px}.empty{padding:25px 10px;text-align:center;color:#8998a5;font-size:13px}@media(max-width:1100px){.decision-grid{grid-template-columns:1fr}.insight-columns{grid-template-columns:1fr}}@media(max-width:640px){.insights-head{flex-direction:column;gap:12px}.insight-panel{padding:16px}.distance-grid{grid-template-columns:repeat(2,1fr)}.insights-head h2,.insight-panel h2{font-size:18px}.evidence-row{gap:8px}.evidence-row time{min-width:67px;font-size:10px}}
</style>
